fn counting_duplicates (text : & str) -> u32 { let mut occurrence = String :: new () ; let mut count : u32 = 0 ; for letter in text . chars () { if text . contains (letter) || occurrence . contains (letter) { occurrence . push (letter) ; } else { count += 1 ; } } count } fn main () { } # [cfg (test)] mod tests { use super :: * ; # [test] fn test_abcde () { assert_eq ! (counting_duplicates ("abcde") , 0) ; } # [test] fn test_abcdea () { assert_eq ! (counting_duplicates ("abcdea") , 1) ; } # [test] fn test_indivisibility () { assert_eq ! (counting_duplicates ("indivisibility") , 1) ; } }